def transform(grid):
    g = [row[:] for row in grid]
    for r, row in enumerate(g):
        cols = [c for c, value in enumerate(row) if value not in (8, 9)]
        for a, b in zip(cols, cols[1:]):
            if b - a > 1:
                for c in range(a + 1, b):
                    g[r][c] = 2
    return g

